import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';

const configUrl = new URL('../../../src/config/index.js', import.meta.url).href;

test('messaging keys load from server secret files with precedence over environment values', t => {
  const directory = mkdtempSync(path.join(tmpdir(), 'messaging-config-'));
  // Fixture file locations are generated by the OS temporary directory API.
  t.after(() => rmSync(directory, { recursive: true, force: true }));
  const waha = path.join(directory, 'waha_api_key');
  const evolution = path.join(directory, 'evolution_api_key');
  // eslint-disable-next-line security/detect-non-literal-fs-filename
  writeFileSync(waha, 'fixture-waha-file\n', { mode: 0o600 });
  // eslint-disable-next-line security/detect-non-literal-fs-filename
  writeFileSync(evolution, 'fixture-evolution-file\n', { mode: 0o600 });
  const code = `
    import assert from 'node:assert/strict';
    const { config } = await import(${JSON.stringify(configUrl)});
    assert.equal(config.WAHA_API_KEY, 'fixture-waha-file');
    assert.equal(config.EVOLUTION_API_KEY, 'fixture-evolution-file');
    assert.equal(config.EVOLUTION_BASE_URL, 'https://example.invalid');
    assert.equal(config.EVOLUTION_INSTANCE, 'fixture');
    assert.equal(config.MESSAGE_PROVIDER_TIMEOUT_MS, 2500);
  `;
  const result = spawnSync(process.execPath, ['--input-type=module', '-e', code], {
    cwd: directory,
    env: { NODE_ENV: 'test', WAHA_API_KEY_FILE: waha, WAHA_API_KEY: 'fixture-env', EVOLUTION_API_KEY_FILE: evolution, EVOLUTION_API_KEY: 'fixture-env', EVOLUTION_BASE_URL: 'https://example.invalid', EVOLUTION_INSTANCE: 'fixture', MESSAGE_PROVIDER_TIMEOUT_MS: '2500' },
    encoding: 'utf8'
  });
  assert.equal(result.status, 0, result.stderr);
});
